import type { Choices, SuggestionOrChoiceType } from './Choice'
import type { StringColumnType } from './String'
import type { Typed } from '../Column'
import type { TableName } from '../Table'
import type { choiceDropdownType } from './Choice'

/**
 * Email format validation (advisory only):
 * - Should contain @ symbol
 * - Format: user@domain
 * Note: Format hints are not strictly enforced by TypeScript
 */
type EmailColumnTypeFormat = `${string}@${string}`

export type EmailColumnType<
    TChoices extends Choices<string> = Choices<string>,
    Dropdown extends choiceDropdownType = choiceDropdownType,
    Type extends SuggestionOrChoiceType<Dropdown, TChoices> & EmailColumnTypeFormat = SuggestionOrChoiceType<
        Dropdown,
        TChoices
    > &
        EmailColumnTypeFormat,
    Default extends Type = Type,
    ReferenceSchema extends TableName = TableName,
> = StringColumnType<TChoices, Dropdown, Type, Default, ReferenceSchema>

/**
 * A Column for an email type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 *   * **maxLength**? - maximum number of characters allowed in this field
 *   * **choices**? - optional choice values for dropdown
 *   * **dropdown**? - dropdown display style
 */
export function EmailColumn<
    const TChoices extends Choices<string>,
    const Type extends SuggestionOrChoiceType<Dropdown, TChoices> & EmailColumnTypeFormat,
    const Default extends Type,
    const C extends EmailColumnType<TChoices, Dropdown, Type, Default, TableName>,
    const Dropdown extends choiceDropdownType = 'none',
>(config: C & EmailColumnType<TChoices, Dropdown, Type, Default, TableName>) {
    return config as Typed<Type, C>
}
